import { loadFont as loadManrope } from "@remotion/google-fonts/Manrope";
import { loadFont as loadDisplay } from "@remotion/google-fonts/Sora";
import React, { forwardRef, useId, useImperativeHandle, useMemo, useRef, type ComponentProps } from "react";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

// Every timing in remocn is written in frames of a 30 fps timeline: a delay
// of 12, a rise over 20, a spring fed `fps`. Read straight from Remotion,
// those numbers mean something else in a 60 fps composition: a tween runs
// twice as fast, while a spring keeps its length, so a scene does not even
// speed up evenly.
//
// These two hooks stand in for Remotion's and answer on that 30 fps timeline
// whatever rate the composition runs at. At 60 fps the frame goes 0, 0.5, 1,
// 1.5: the scene lasts the same number of seconds and every frame in between
// is a new picture. At 30 fps they return exactly what Remotion does.
//
//   const frame = useSceneFrame();
//   const { fps, width } = useSceneConfig();
//
// What a component hands back to Remotion is still counted in the
// composition's own frames: `from` and `durationInFrames` of a `<Sequence>`,
// the length of a transition. `useCompositionFrames()` converts those.

/** The frame rate remocn timings are written in. */
const SCENE_FPS = 30;

/** `useCurrentFrame()` in 30 fps frames; fractional above 30 fps. */
function useSceneFrame(): number {
  const { fps } = useVideoConfig();
  return (useCurrentFrame() * SCENE_FPS) / fps;
}

/**
 * `useVideoConfig()` on the 30 fps timeline: `fps` is 30 and
 * `durationInFrames` counts 30 fps frames. Size and the rest are untouched.
 */
function useSceneConfig(): ReturnType<typeof useVideoConfig> {
  const config = useVideoConfig();
  return useMemo(
    () => ({
      ...config,
      fps: SCENE_FPS,
      durationInFrames: (config.durationInFrames * SCENE_FPS) / config.fps,
    }),
    [config],
  );
}

/**
 * Turns a count of 30 fps frames into the composition's own, for what
 * Remotion itself reads: `<Sequence from={frames(24)}>`. Whole frames only,
 * as Remotion requires.
 */
function useCompositionFrames(): (sceneFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (sceneFrames: number) => Math.round((sceneFrames * fps) / SCENE_FPS),
    [fps],
  );
}

/**
 * The other way round: a count Remotion gives a component in the
 * composition's own frames, in 30 fps frames. A transition's presentation
 * gets its length that way (`presentationDurationInFrames`).
 */
function useSceneFrameCount(): (compositionFrames: number) => number {
  const { fps } = useVideoConfig();
  return useMemo(
    () => (compositionFrames: number) => (compositionFrames * SCENE_FPS) / fps,
    [fps],
  );
}

// A component's schedule, kept apart from its drawing: which elements the
// animation has (an entry, a word, a finale), when each starts and how long
// it runs. The schedule is a pure function of the props, so it can be read
// without rendering anything, and a `timing` prop can move, trim or stretch
// single elements without touching the code that draws them.
//
//   // timeline.ts, next to the component
//   export const titleTimeline = defineTimeline<TitleElementId, TitleProps>(
//     ({ words = WORDS }, { length }) =>
//       words.map((word, k) => ({
//         id: `word:${k}`,
//         lane: "Words",
//         label: word,
//         start: k * 8,
//         length: 8,
//         follows: k > 0 ? `word:${k - 1}` : undefined,
//         beats: { rise: 12 },
//       })),
//   );
//
//   // index.tsx
//   const tl = useTimeline(titleTimeline, props, length, timing);
//   const word = tl.get("word:0");
//   interpolate(t, [word.start, word.start + word.beat("rise")], [0, 1]);
//
// Every number is in frames of the 30 fps scene timeline, after `delay` and
// `speed`: those still apply to the whole animation, `timing` works inside it.
// Element ids are public API: a saved `timing` refers to them, so an id once
// shipped keeps its meaning.

/** One timed part of an animation, as its schedule lays it out. */
interface TimelineElement<Id extends string = string> {
  /** Stable name a `timing` override refers to: `entry:0`, `finale`. */
  id: Id;
  /** Row the element sits on in a timeline view. */
  lane: string;
  /** What the element shows, for people reading the timeline. */
  label: string;
  /** First frame of the element. */
  start: number;
  /** Frames until the next element of the lane takes over, or the end. */
  length: number;
  /**
   * The element this one comes after. When that element's end moves, this
   * one moves with it, keeping the gap between them.
   */
  follows?: Id;
  /**
   * Named frame counts inside the element, measured from its start: how long
   * a roll takes, when a second part begins. `stretch` scales them.
   */
  beats?: Record<string, number>;
}

/** A change to one element, made from outside the component. */
interface TimingOverride {
  /** New first frame. Wins over the shift from `follows`. */
  start?: number;
  /** New length, trimming or extending the element. Wins over `stretch`. */
  length?: number;
  /** Multiplies the length and every beat: 2 plays the element half as fast. */
  stretch?: number;
  /** Stops following: the element keeps its own start when the one before moves. */
  detach?: boolean;
}

/** Overrides by element id: the `timing` prop of a component. */
type Timing<Id extends string = string> = Partial<
  Record<Id, TimingOverride>
>;

/** A component's schedule: props and the scene length in, elements out. */
type Schedule<Id extends string, Props> = (
  props: Props,
  scene: { length: number },
) => TimelineElement<Id>[];

/** An element after `timing` has been applied. */
interface ResolvedElement<Id extends string = string>
  extends TimelineElement<Id> {
  /** `start + length`. */
  end: number;
  beats: Record<string, number>;
  /** A beat by name, stretched. Throws on a name the schedule didn't set. */
  beat(name: string): number;
  /**
   * 0 → 1 over the element, or over its first `beat` frames when a beat is
   * named. Clamped on both sides.
   */
  progress(frame: number, beat?: string): number;
}

interface ResolvedTimeline<Id extends string = string> {
  /** All elements, in the order the schedule returned them. */
  elements: ResolvedElement<Id>[];
  /** An element by id. Throws on an id the schedule didn't return. */
  get(id: Id): ResolvedElement<Id>;
  /** The elements of one lane, in order. */
  lane(name: string): ResolvedElement<Id>[];
}

/** Declares a schedule. Elements come back in time order. */
function defineTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
): Schedule<Id, Props> {
  return schedule;
}

/** Applies `timing` to a schedule's elements and carries the `follows` chains. */
function resolve<Id extends string>(
  elements: TimelineElement<Id>[],
  timing: Timing<Id> = {},
): ResolvedTimeline<Id> {
  const byId = new Map<Id, TimelineElement<Id>>(elements.map((e) => [e.id, e]));
  const done = new Map<Id, ResolvedElement<Id>>();
  const visiting = new Set<Id>();

  const place = (element: TimelineElement<Id>): ResolvedElement<Id> => {
    const known = done.get(element.id);
    if (known) return known;
    if (visiting.has(element.id)) {
      throw new Error(`timeline: "${element.id}" follows itself`);
    }
    visiting.add(element.id);

    const override: TimingOverride = timing[element.id] ?? {};
    const stretch = override.stretch ?? 1;
    const beats: Record<string, number> = {};
    for (const [name, frames] of Object.entries(element.beats ?? {})) {
      beats[name] = frames * stretch;
    }

    let start = element.start;
    const leader = element.follows ? byId.get(element.follows) : undefined;
    if (leader && !override.detach) {
      // The leader's end moved by this much; this element moves as far.
      start += place(leader).end - (leader.start + leader.length);
    }
    if (override.start !== undefined) start = override.start;
    const length = override.length ?? element.length * stretch;

    const beat = (name: string) => {
      const frames = beats[name];
      if (frames === undefined) {
        throw new Error(`timeline: "${element.id}" has no beat "${name}"`);
      }
      return frames;
    };
    const resolved: ResolvedElement<Id> = {
      ...element,
      start,
      length,
      end: start + length,
      beats,
      beat,
      progress: (frame, name) => {
        const span = name === undefined ? length : beat(name);
        if (span <= 0) return frame >= start ? 1 : 0;
        return Math.min(1, Math.max(0, (frame - start) / span));
      },
    };
    visiting.delete(element.id);
    done.set(element.id, resolved);
    return resolved;
  };

  const all = elements.map(place);
  return {
    elements: all,
    get: (id) => {
      const element = done.get(id);
      if (!element) throw new Error(`timeline: no element "${id}"`);
      return element;
    },
    lane: (name) => all.filter((e) => e.lane === name),
  };
}

/**
 * The component side: runs the schedule and applies `timing`, once per
 * change of its inputs. `length` is the scene length the schedule fits into,
 * in the same frames the component counts.
 */
function useTimeline<Id extends string, Props>(
  schedule: Schedule<Id, Props>,
  props: Props,
  length: number,
  timing?: Timing<Id>,
): ResolvedTimeline<Id> {
  return useMemo(
    () => resolve(schedule(props, { length }), timing),
    [schedule, props, length, timing],
  );
}

// Strobe cuts through the words, each a field of its own, to the poster with
// the last word and the logo. Frames on the 30 fps scene timeline, after
// `delay` and `speed`. The ids are public: a saved `timing` prop refers to
// them.

type StrobeWordsElementId = `cut:${number}` | "poster";

interface StrobeWordsTimingProps {
  words?: string[];
  rhythm?: number[];
  beat?: number;
  cuts?: number;
}

const DEFAULT_WORDS = ["Plan.", "Write.", "Render.", "Ship."];
const BEAT = 6;
const CUTS = 13;
/** The poster's glow rises over this many frames. */
const POSTER_RISE = 60;

/** The words shown, a fallback when there are none. */
function listOf(words: string[]) {
  return words.length > 0 ? words : ["Ship."];
}

function defaultRhythm(count: number, beat: number, cuts: number) {
  let n = count - 1;
  while (n < cuts) n += count;
  return Array.from({ length: n }, (_, i) =>
    Math.round(beat - ((beat / 2) * i) / Math.max(1, n - 1)),
  );
}

/** The word on cut `index` of `cuts`: the cuts end on the word before the last. */
function cutWord(list: string[], index: number, cuts: number) {
  return list[
    (((index - cuts + list.length - 1) % list.length) + list.length) %
      list.length
  ];
}

// `cut:<i>` holds until the next cut; the poster follows the last cut and
// holds to the end, its glow rising over its length.
const strobeWordsTimeline = defineTimeline<
  StrobeWordsElementId,
  StrobeWordsTimingProps
>(({ words = DEFAULT_WORDS, rhythm, beat = BEAT, cuts = CUTS }) => {
  const list = listOf(words);
  const beats =
    rhythm && rhythm.length > 0
      ? rhythm
      : defaultRhythm(list.length, beat, cuts);
  const elements: TimelineElement<StrobeWordsElementId>[] = [];
  let at = 0;
  for (let i = 0; i < beats.length; i++) {
    elements.push({
      id: `cut:${i}`,
      lane: "Cuts",
      label: cutWord(list, i, beats.length),
      start: at,
      length: beats[i],
      follows: i > 0 ? `cut:${i - 1}` : undefined,
    });
    at += beats[i];
  }
  elements.push({
    id: "poster",
    lane: "Poster",
    label: list[list.length - 1],
    start: at,
    length: POSTER_RISE,
    follows: beats.length > 0 ? `cut:${beats.length - 1}` : undefined,
  });
  return elements;
});

const manrope = loadManrope("normal", {
  weights: ["500", "600"],
  subsets: ["latin"],
});
const { fontFamily: display } = loadDisplay("normal", {
  weights: ["500"],
  subsets: ["latin"],
});

// gradients.sh "radial-glow" palette (bg #020204): #f3f1ff, #9db4ff, #5a46cb, #1d1240.
const GLOW = ["#f3f1ff", "#9db4ff", "#5a46cb", "#1d1240", "#020204"] as const;

// Sora 500 advances (1/1000 em), ASCII 32–126, measured with HarfBuzz.
const SORA_500 = [
  222, 303, 452, 702, 652, 864, 702, 264, 382, 382, 568, 592, 266, 506, 266,
  365, 750, 423, 623, 620, 652, 630, 668, 585, 647, 668, 266, 266, 592, 590,
  592, 556, 1124, 765, 684, 797, 788, 598, 560, 832, 803, 320, 641, 703, 549,
  937, 858, 865, 649, 865, 710, 682, 602, 785, 719, 1052, 705, 654, 652, 382,
  365, 382, 587, 581, 300, 581, 694, 608, 694, 616, 380, 679, 644, 317, 324,
  595, 296, 973, 644, 678, 694, 694, 414, 543, 429, 634, 572, 873, 574, 555,
  493, 382, 375, 382, 511,
];
const TRACK = -0.045;

const REMOCN_R_PATH =
  "M 0.01 0.81 C 0.01 1.73, 0.36 2.79, 1.09 4.13 C 4.91 11.04, 13.45 17.16, 21.7 18.9 C 22.94 19.16, 23.18 19.16, 51.39 19.27 C 76.07 19.36, 80.02 19.4, 81.32 19.57 C 89.89 20.69, 96.2 24.68, 99.38 31.01 C 103.19 38.56, 102.53 50.1, 97.91 57.07 C 94.66 61.96, 89.68 64.99, 83.26 66 C 82.81 66.07, 70.18 66.83, 55.2 67.69 C 24.82 69.43, 27.03 69.23, 24.18 70.4 C 19.9 72.15, 14.84 75.7, 10.65 79.89 C 4.86 85.68, 1.3 91.91, 0.25 98.13 C 0.12 98.85, 0.08 103.13, 0.04 116.66 L 0 134.26 9.5 134.26 L 19 134.26 19.05 119.41 C 19.1 103.27, 19.08 103.82, 19.82 101.04 C 21.79 93.65, 27.86 88.75, 36.45 87.63 C 37.23 87.53, 39.41 87.5, 43.57 87.53 C 50.12 87.59, 50.75 87.65, 53.22 88.45 C 56.61 89.56, 59.67 91.86, 62.02 95.07 C 62.52 95.76, 69.35 103.85, 77.2 113.07 C 85.04 122.28, 91.63 130.04, 91.85 130.32 C 92.07 130.59, 92.5 131.34, 92.82 131.97 C 93.52 133.35, 94.11 133.93, 95.06 134.13 C 95.5 134.23, 98.97 134.26, 106.36 134.23 L 117.01 134.19 100.82 113.07 C 91.91 101.45, 84.52 91.78, 84.39 91.57 C 83.36 89.89, 83.66 87.53, 85.09 86 C 85.79 85.25, 86.36 84.94, 88.07 84.38 C 96.18 81.72, 104.15 76.62, 109.97 70.36 C 120.59 58.93, 124.06 44.32, 119.44 30.43 C 114.59 15.81, 101.93 4.02, 87.64 0.83 C 83.93 0.01, 88.09 0.08, 41.85 0.04 L 0.01 0 0.01 0.81 Z";

/** Full logo as on remocn.dev: R mark (0.76em tall, baseline-aligned) + "emocn" in Manrope 600, tracking-tight. */
function RemocnLogo({ fontSize, color }: { fontSize: number; color: string }) {
  return (
    <div
      style={{
        display: "flex",
        alignItems: "baseline",
        color,
        fontFamily: manrope.fontFamily,
        fontWeight: 600,
        fontSize,
        letterSpacing: "-0.025em",
        lineHeight: 1,
      }}
    >
      <svg
        viewBox="0 0 124.06 134.26"
        style={{ height: "0.76em", width: "auto" }}
        aria-hidden
      >
        <path fill="currentColor" d={REMOCN_R_PATH} />
      </svg>
      <span style={{ marginLeft: "0.04em" }}>emocn</span>
    </div>
  );
}

interface StrobeWordsProps {
  words?: string[];
  rhythm?: number[];
  /** Frames of the first strobe cut when `rhythm` is unset; cuts speed up to half that. */
  beat?: number;
  /** Fewest strobe cuts before the poster when `rhythm` is unset. */
  cuts?: number;
  logo?: React.ReactNode;
  accent?: string;
  /** Typeface for the words. Load it yourself; Sora by default. */
  fontFamily?: string;
  /** Film grain over the scene. */
  grain?: boolean;
  /** Size of the words and logo, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches single strobe cuts and the poster, by the ids
   * in `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<StrobeWordsElementId>;
}

const CAP = 0.73;
const BASE = 0.84;
const INK = "#0A0A0B";
const PAPER = "#F5F4F0";
const PAPER_INK = "#121214";

type Field = "accent" | "ink" | "paper";
const CYCLE: Field[] = ["accent", "ink", "paper"];

function widthEm(text: string) {
  let w = 0;
  for (const ch of text) {
    const code = ch.charCodeAt(0);
    const adv = code >= 32 && code < 127 ? SORA_500[code - 32] : 600;
    w += adv / 1000 + TRACK;
  }
  return Math.max(w, 0.5);
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={3}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

function Word({
  text,
  size,
  color,
  stop,
  fill,
  fontFamily,
}: {
  text: string;
  size: number;
  color: string;
  stop: string;
  fill?: string;
  fontFamily: string;
}) {
  const { height: H } = useSceneConfig();
  const baseline = H / 2 + (CAP * size) / 2;
  const tail = text.match(/[.!?]$/) ? text.slice(-1) : "";
  const body = tail ? text.slice(0, -1) : text;
  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        right: 0,
        top: baseline - BASE * size,
        display: "flex",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          fontFamily,
          fontWeight: 500,
          fontSize: size,
          lineHeight: 1,
          letterSpacing: `${TRACK}em`,
          paddingLeft: `${-TRACK}em`,
          whiteSpace: "nowrap",
          color,
        }}
      >
        {fill ? (
          <span
            style={{
              color: "transparent",
              backgroundImage: fill,
              WebkitBackgroundClip: "text",
              backgroundClip: "text",
              paddingRight: "0.08em",
              marginRight: "-0.08em",
            }}
          >
            {body}
          </span>
        ) : (
          body
        )}
        {tail ? <span style={{ color: stop }}>{tail}</span> : null}
      </div>
    </div>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function StrobeWordsBase(props: StrobeWordsProps) {
  const {
    words = DEFAULT_WORDS,
    logo,
    accent = "#3B5BFD",
    fontFamily = display,
    grain = true,
    scale = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    strobeWordsTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const u = H / 720;
  const list = listOf(words);
  const cutEls = tl.lane("Cuts");
  const posterEl = tl.get("poster");
  const cutCount = cutEls.length;
  const poster: Field = theme === "light" ? "paper" : "ink";

  const offset = (((CYCLE.indexOf("accent") - (cutCount - 1)) % 3) + 3) % 3;

  // On screen: the last cut started, or the poster once it has.
  let index = 0;
  cutEls.forEach((e, i) => {
    if (t >= e.start) index = i;
  });
  if (t >= posterEl.start) index = cutCount;
  const isPoster = index >= cutCount;
  const field: Field = isPoster ? poster : CYCLE[(index + offset) % 3];
  const text = isPoster
    ? list[list.length - 1]
    : cutWord(list, index, cutCount);

  // Each strobe beat on the accent field is a radial-glow ground; the disc
  // sits in a slightly different place per beat so the cuts read as light.
  const k = isPoster ? 0 : index;
  const bx = 50 + ((k * 37) % 5) * 5 - 10;
  const glowField = [
    `radial-gradient(52% 64% at ${bx}% 104%, ${GLOW[0]} 0%, color-mix(in oklab, ${GLOW[1]} 85%, transparent) 30%, transparent 72%)`,
    `radial-gradient(90% 90% at ${100 - bx}% 0%, color-mix(in oklab, ${GLOW[3]} 80%, transparent) 0%, transparent 70%)`,
    `linear-gradient(180deg, ${GLOW[3]} 0%, ${GLOW[2]} 62%, #7e6fe0 100%)`,
  ].join(", ");
  const rise = interpolate(t - posterEl.start, [0, posterEl.length], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.22, 1, 0.36, 1),
  });
  // Poster: the glow's ring reads as a horizon arc low in frame, rising a
  // few percent over the hold, under the word rather than around it.
  const posterGlow = [
    `radial-gradient(78% 62% at 50% ${142 - 6 * rise}%, color-mix(in oklab, ${GLOW[3]} 90%, transparent) 60%, color-mix(in oklab, ${GLOW[0]} 80%, transparent) 63%, color-mix(in oklab, ${GLOW[1]} 40%, transparent) 67%, transparent 80%)`,
    `radial-gradient(90% 60% at 50% 120%, color-mix(in oklab, ${GLOW[2]} 45%, transparent) 0%, transparent 70%)`,
    GLOW[4],
  ].join(", ");
  const bg =
    field === "accent"
      ? glowField
      : field === "ink"
        ? isPoster
          ? posterGlow
          : INK
        : PAPER;
  const fg = field === "paper" ? PAPER_INK : "#F7F7F5";
  const stop = field === "accent" ? GLOW[0] : accent;
  const posterFill =
    isPoster && field === "paper"
      ? `linear-gradient(180deg, ${GLOW[2]} 10%, ${GLOW[3]} 92%)`
      : undefined;

  const longest = list.reduce((m, w) => Math.max(m, widthEm(w)), 0.5);
  const strobeSize = Math.min(290 * u, (0.74 * W) / longest);
  const final = list[list.length - 1];
  const posterSize = Math.min(340 * u, (0.8 * W) / widthEm(final));

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <Word
          text={text}
          size={isPoster ? posterSize : strobeSize}
          color={fg}
          stop={stop}
          fill={posterFill}
          fontFamily={fontFamily}
        />
        {isPoster ? (
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              bottom: 0.085 * H,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              gap: 10 * u,
              color: fg,
            }}
          >
            {logo ?? <RemocnLogo fontSize={28 * u} color={fg} />}
          </div>
        ) : null}
      </ScaleLayer>
      {grain ? <Grain opacity={field === "paper" ? 0.04 : 0.05} /> : null}
    </AbsoluteFill>
  );
}

