const ELEMENT_PROP_KEYS = new Set(["theme","beat","cuts","accent","fontFamily","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  beat: 6,
  cuts: 13,
